//! Cross-validation tests against the R CPASSOC reference (`FunctionSet.R`).
//!
//! Golden values were generated by `generate_golden.R` (sourced from
//! `reference/FunctionSet.R`) and saved to `golden_values.json`.
//!
//! To regenerate golden values:
//! ```bash
//! conda activate r45
//! Rscript bio_crates/cpassoc/tests/generate_golden.R
//! ```
//!
//! ## Test coverage
//!
//! | Test                     | R function                  | Tolerance  |
//! |--------------------------|-----------------------------|------------|
//! | `shom_test1`             | `SHom` (3×2)                | 1e-8       |
//! | `shom_test2`             | `SHom` (5×3)                | 1e-8       |
//! | `shet_test1`             | `SHet` (3×2, correct=1)     | 1e-8       |
//! | `shet_test2`             | `SHet` (5×3, correct=1)     | 1e-8       |
//! | `shet_nocorrect`         | `SHet` (correct=0)          | 1e-8       |
//! | `shet_seq`               | `SHet` (fixed cutoffs)      | 1e-8       |
//! | `corr_matrix`            | `cor(X)`                    | 1e-8       |
//! | `weight_vector`          | normalised weights          | 1e-12      |
//! | `shom_single`            | edge case: 1 row            | 1e-8       |
//! | `shet_single`            | edge case: 1 row            | 1e-8       |
//! | `shet_opposite_effects`  | correct=1 vs correct=0      | 1e-8       |
//! | `shom_pvalue`            | `pchisq(..., lower.tail=F)` | 1e-10      |
//! | `shet_pvalue`            | `pgamma(..., lower.tail=F)` | 1e-10      |
//! | `gamma_convergence`      | `EstimateGamma` (k,θ,a)     | see test   |

use cpassoc::distr;
use cpassoc::gamma;
use cpassoc::input;
use cpassoc::stats::{self, ShetOptions};
use faer::Mat;
use serde_json::Value;

/// Tolerance for exact-arithmentic comparisons (SHom, SHet, corr, weights).
const TOL: f64 = 1e-8;

/// Tolerance for p-value comparisons.
const P_TOL: f64 = 1e-10;

fn load_golden() -> Value {
    let json = include_str!("golden_values.json");
    serde_json::from_str(json).expect("failed to parse golden_values.json")
}

// ─── Test matrices (must match generate_golden.R exactly) ───────────────────

fn x1() -> Mat<f64> {
    // 3×2: c(1.5, 2.0, -1.0, 0.5, 3.0, 1.5) byrow=FALSE
    // R fills column-major: col0=[1.5,2.0,-1.0], col1=[0.5,3.0,1.5]
    Mat::from_fn(3, 2, |i, j| match (i, j) {
        (0, 0) => 1.5,
        (1, 0) => 2.0,
        (2, 0) => -1.0,
        (0, 1) => 0.5,
        (1, 1) => 3.0,
        (2, 1) => 1.5,
        _ => unreachable!(),
    })
}

fn x2() -> Mat<f64> {
    // 5×3: R fills column-major from c(2.0,1.5,0.5,-1.0,3.0, 1.0,2.5,1.0,0.5,2.0, 0.5,1.0,3.0,-2.0,1.5)
    // col0=[2,1.5,0.5,-1,3], col1=[1,2.5,1,0.5,2], col2=[0.5,1,3,-2,1.5]
    Mat::from_fn(5, 3, |i, j| match (i, j) {
        (0, 0) => 2.0,
        (1, 0) => 1.5,
        (2, 0) => 0.5,
        (3, 0) => -1.0,
        (4, 0) => 3.0,
        (0, 1) => 1.0,
        (1, 1) => 2.5,
        (2, 1) => 1.0,
        (3, 1) => 0.5,
        (4, 1) => 2.0,
        (0, 2) => 0.5,
        (1, 2) => 1.0,
        (2, 2) => 3.0,
        (3, 2) => -2.0,
        (4, 2) => 1.5,
        _ => unreachable!(),
    })
}

fn sample_size1() -> Vec<f64> {
    vec![1000.0, 800.0]
}

fn sample_size2() -> Vec<f64> {
    vec![1000.0, 1500.0, 800.0]
}

fn corr1() -> Mat<f64> {
    // [[1, 0.3], [0.3, 1]]
    Mat::from_fn(2, 2, |i, j| if i == j { 1.0 } else { 0.3 })
}

fn corr2() -> Mat<f64> {
    // [[1, 0.3, 0.1], [0.3, 1, 0.5], [0.1, 0.5, 1]]
    Mat::from_fn(3, 3, |i, j| match (i, j) {
        (0, 0) | (1, 1) | (2, 2) => 1.0,
        (0, 1) | (1, 0) => 0.3,
        (0, 2) | (2, 0) => 0.1,
        (1, 2) | (2, 1) => 0.5,
        _ => unreachable!(),
    })
}

fn json_to_f64_vec(v: &Value) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap())
        .collect()
}

fn assert_close(a: f64, b: f64, tol: f64, ctx: &str) {
    let diff = (a - b).abs();
    assert!(
        diff < tol,
        "{ctx}: Rust={a}, R={b}, |diff|={diff} (tol={tol})"
    );
}

// ─── SHom tests ─────────────────────────────────────────────────────────────

#[test]
fn shom_test1() {
    let golden = load_golden();
    let result = stats::shom(&x1(), &sample_size1(), &corr1());
    let expected = json_to_f64_vec(&golden["shom_test1"]);
    assert_eq!(result.len(), expected.len());
    for (i, (r, e)) in result.iter().zip(&expected).enumerate() {
        assert_close(*r, *e, TOL, &format!("SHom test1 SNP {i}"));
    }
}

#[test]
fn shom_test2() {
    let golden = load_golden();
    let result = stats::shom(&x2(), &sample_size2(), &corr2());
    let expected = json_to_f64_vec(&golden["shom_test2"]);
    assert_eq!(result.len(), expected.len());
    for (i, (r, e)) in result.iter().zip(&expected).enumerate() {
        assert_close(*r, *e, TOL, &format!("SHom test2 SNP {i}"));
    }
}

