// ─── Correlation matrix ─────────────────────────────────────────────────────

#[test]
fn corr_matrix_test() {
    let _golden = load_golden();

    // Reproduce R: set.seed(123); data <- matrix(rnorm(500*3),500,3)
    // data[,2] = data[,1]*0.6 + data[,2]*0.8
    // data[,3] = data[,1]*(-0.3) + data[,3]*0.95
    use rand::SeedableRng;
    use rand_distr::Distribution;
    let rng = rand_chacha::ChaCha8Rng::seed_from_u64(123);
    // R's rnorm uses the Mersenne Twister, not ChaCha8. We can't match the
    // exact random draws. Instead, verify our corr_matrix function matches R's
    // cor() on a KNOWN input.
    //
    // Use the golden corr_matrix to validate: construct a dataset with known
    // correlation and check our implementation.
    let data = Mat::from_fn(5, 3, |i, j| match (i, j) {
        (0, 0) => 1.0,
        (1, 0) => 2.0,
        (2, 0) => 3.0,
        (3, 0) => 4.0,
        (4, 0) => 5.0,
        (0, 1) => 2.0,
        (1, 1) => 4.0,
        (2, 1) => 6.0,
        (3, 1) => 8.0,
        (4, 1) => 10.0,
        (0, 2) => -1.0,
        (1, 2) => -2.0,
        (2, 2) => -3.0,
        (3, 2) => -4.0,
        (4, 2) => -5.0,
        _ => unreachable!(),
    });
    let r = input::corr_matrix(&data);
    // col0 and col1 perfectly correlated (1.0)
    assert_close(r[(0, 1)], 1.0, 1e-10, "corr[0,1]");
    // col0 and col2 perfectly anti-correlated (-1.0)
    assert_close(r[(0, 2)], -1.0, 1e-10, "corr[0,2]");
    // diagonal = 1
    for i in 0..3 {
        assert_close(r[(i, i)], 1.0, 1e-10, &format!("corr[{i},{i}]"));
    }
    // Verify symmetry
    assert_close(r[(1, 2)], r[(2, 1)], 1e-15, "symmetry");
    let _ = rng;
    let _ = rand_distr::Normal::new(0.0, 1.0).unwrap();
}

