// ─── Single-row edge cases ──────────────────────────────────────────────────

#[test]
fn shom_single() {
    let golden = load_golden();
    let x = Mat::from_fn(1, 3, |_, j| match j {
        0 => 2.5,
        1 => -1.5,
        2 => 0.8,
        _ => unreachable!(),
    });
    let result = stats::shom(&x, &sample_size2(), &corr2());
    let expected = golden["shom_single"].as_f64().unwrap();
    assert_close(result[0], expected, TOL, "SHom single");
}

#[test]
fn shet_single() {
    let golden = load_golden();
    let x = Mat::from_fn(1, 3, |_, j| match j {
        0 => 2.5,
        1 => -1.5,
        2 => 0.8,
        _ => unreachable!(),
    });
    let result = stats::shet(&x, &sample_size2(), &corr2(), ShetOptions::default());
    let expected = golden["shet_single"].as_f64().unwrap();
    assert_close(result[0], expected, TOL, "SHet single");
}

// ─── Opposite effects (correct=1 vs correct=0) ──────────────────────────────

#[test]
fn shet_opposite_effects() {
    let golden = load_golden();
    // 2×3 matrix, byrow=TRUE: [[2,-2,1.5],[-1.5,0.5,-0.5]]
    let x = Mat::from_fn(2, 3, |i, j| match (i, j) {
        (0, 0) => 2.0,
        (0, 1) => -2.0,
        (0, 2) => 1.5,
        (1, 0) => -1.5,
        (1, 1) => 0.5,
        (1, 2) => -0.5,
        _ => unreachable!(),
    });

    let opts_c1 = ShetOptions {
        correct: 1,
        ..Default::default()
    };
    let opts_c0 = ShetOptions {
        correct: 0,
        ..Default::default()
    };

    let result_c1 = stats::shet(&x, &sample_size2(), &corr2(), opts_c1);
    let expected_c1 = json_to_f64_vec(&golden["shet_opp_correct1"]);
    for (i, (r, e)) in result_c1.iter().zip(&expected_c1).enumerate() {
        assert_close(*r, *e, TOL, &format!("SHet opp c1 SNP {i}"));
    }

    let result_c0 = stats::shet(&x, &sample_size2(), &corr2(), opts_c0);
    let expected_c0 = json_to_f64_vec(&golden["shet_opp_correct0"]);
    for (i, (r, e)) in result_c0.iter().zip(&expected_c0).enumerate() {
        assert_close(*r, *e, TOL, &format!("SHet opp c0 SNP {i}"));
    }

    let result_shom = stats::shom(&x, &sample_size2(), &corr2());
    let expected_shom = json_to_f64_vec(&golden["shom_opp"]);
    for (i, (r, e)) in result_shom.iter().zip(&expected_shom).enumerate() {
        assert_close(*r, *e, TOL, &format!("SHom opp SNP {i}"));
    }
}

// ─── P-value tests ──────────────────────────────────────────────────────────

#[test]
fn shom_pvalue_test() {
    let golden = load_golden();
    let shom_stats = stats::shom(&x2(), &sample_size2(), &corr2());
    let expected = json_to_f64_vec(&golden["shom_pvalue"]);
    for (i, (&s, e)) in shom_stats.iter().zip(&expected).enumerate() {
        let p = distr::shom_pvalue(s);
        assert_close(p, *e, P_TOL, &format!("SHom pvalue SNP {i}"));
    }
}

#[test]
fn shet_pvalue_test() {
    let golden = load_golden();
    // Use the golden gamma params (from gamma_test)
    let gamma_arr = json_to_f64_vec(&golden["gamma_test"]);
    let params = gamma::GammaParams {
        shape: gamma_arr[0],
        scale: gamma_arr[1],
        shift: gamma_arr[2],
    };
    let shet_stats = stats::shet(&x2(), &sample_size2(), &corr2(), ShetOptions::default());
    let expected = json_to_f64_vec(&golden["shet_pvalue"]);
    for (i, (&s, e)) in shet_stats.iter().zip(&expected).enumerate() {
        let p = distr::shet_pvalue(s, params);
        assert_close(p, *e, P_TOL, &format!("SHet pvalue SNP {i}"));
    }
}

// ─── Gamma fitting (distributional convergence) ─────────────────────────────
//
// R and Rust use different RNG streams (MASS::mvrnorm vs ChaCha8), so we
// cannot match gamma parameters exactly. Instead we validate:
// 1. That the Rust gamma fit produces reasonable parameters for the same
//    correlation matrix (same order of magnitude as R).
// 2. That the shifted-gamma p-values from the Rust fit are close to R for the
//    test SNPs (the gamma is a smooth approximation, so moderate parameter
//    differences should yield similar p-values in the non-extreme tail).

#[test]
fn gamma_fit_convergence() {
    // Fit with a large N to get stable parameters
    let params = gamma::estimate_gamma(
        100_000,
        &sample_size2(),
        &corr2(),
        ShetOptions::default(),
        42,
    );

    // R golden: shape=1.554, scale=1.763, shift=-0.0796
    // With different RNG, expect same order of magnitude.
    assert!(
        params.shape > 0.5 && params.shape < 3.0,
        "shape {} out of expected range",
        params.shape
    );
    assert!(
        params.scale > 0.5 && params.scale < 4.0,
        "scale {} out of expected range",
        params.scale
    );
    assert!(
        params.shift.abs() < 1.0,
        "shift {} out of expected range",
        params.shift
    );

    // The key property: SHet p-values should be in a reasonable range
    let shet_stats = stats::shet(&x2(), &sample_size2(), &corr2(), ShetOptions::default());
    for &s in &shet_stats {
        let p = distr::shet_pvalue(s, params);
        assert!((0.0..=1.0).contains(&p), "p-value {p} out of [0,1]");
    }
}

#[test]
fn gamma_fit_two_trait() {
    // 2-trait case (R golden: shape=0.747, scale=2.211, shift=0.233)
    let params = gamma::estimate_gamma(
        100_000,
        &sample_size1(),
        &corr1(),
        ShetOptions::default(),
        42,
    );

    assert!(
        params.shape > 0.3 && params.shape < 1.5,
        "shape {} out of expected range",
        params.shape
    );
    assert!(
        params.scale > 1.0 && params.scale < 4.0,
        "scale {} out of expected range",
        params.scale
    );
}

// ─── Empirical distribution p-value ─────────────────────────────────────────

#[test]
fn empirical_dist_basic() {
    let null = gamma::emp_dist(
        50_000,
        &sample_size2(),
        &corr2(),
        ShetOptions::default(),
        42,
    );
    assert_eq!(null.len(), 50_000);

    // The empirical p-value for a moderate statistic should be in (0, 0.5)
    let p = gamma::empirical_pvalue(&null, 5.0);
    assert!(p > 0.0 && p < 0.5, "empirical p={p}");

    // Very large statistic should give very small p-value
    let p_large = gamma::empirical_pvalue(&null, 50.0);
    assert!(p_large < 0.01, "p_large={p_large}");
}

// ─── Full pipeline test ─────────────────────────────────────────────────────

#[test]
fn run_cpassoc_pipeline() {
    use cpassoc::{CpassocConfig, run_cpassoc};

    let config = CpassocConfig {
        sample_size: sample_size2(),
        shet_opts: ShetOptions::default(),
        n_sim: 10_000,
        seed: 42,
    };

    let results = run_cpassoc(&x2(), &corr2(), &config, None);

    assert_eq!(results.len(), 5);

    // Check SHom values match golden
    let golden = load_golden();
    let expected_shom = json_to_f64_vec(&golden["shom_test2"]);
    for (i, (r, e)) in results.iter().zip(&expected_shom).enumerate() {
        assert_close(r.shom, *e, TOL, &format!("pipeline SHom SNP {i}"));
    }

    // Check SHet values match golden
    let expected_shet = json_to_f64_vec(&golden["shet_test2"]);
    for (i, (r, e)) in results.iter().zip(&expected_shet).enumerate() {
        assert_close(r.shet, *e, TOL, &format!("pipeline SHet SNP {i}"));
    }

    // Check SHom p-values match golden
    let expected_shom_p = json_to_f64_vec(&golden["shom_pvalue"]);
    for (i, (r, e)) in results.iter().zip(&expected_shom_p).enumerate() {
        assert_close(r.shom_p, *e, P_TOL, &format!("pipeline SHom-p SNP {i}"));
    }

    // All SHet p-values should be valid
    for r in &results {
        assert!(r.shet_p >= 0.0 && r.shet_p <= 1.0, "SHet p out of range");
    }
}
